-- =========================================================
--  Amábilis & Espinosa — Catálogo de propiedades en Supabase
--  Ejecuta este archivo completo en: Supabase → SQL Editor → New query → Run
--  Es idempotente: puedes volver a ejecutarlo sin romper nada.
-- =========================================================

-- 1. Tabla -------------------------------------------------
create table if not exists public.properties (
  id           text primary key,
  title        text not null,
  zone         text,
  location     text,
  type         text,
  operation    text,
  price        numeric,
  beds         numeric,
  baths        numeric,
  parking      integer,
  built        numeric,
  land         numeric,
  featured     boolean not null default false,
  tag          text,
  summary      text,
  description  text,
  amenities    text[] not null default '{}',
  images       text[] not null default '{}',
  alts         text[] not null default '{}',
  en           jsonb,
  published    boolean not null default true,
  position     integer not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

comment on column public.properties.en is 'Traducciones al inglés: {title, summary, description, amenities[]}';
comment on column public.properties.position is 'Orden de aparición en el sitio (menor primero)';

-- Marca de tiempo automática al editar
create or replace function public.tocar_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;

drop trigger if exists properties_updated_at on public.properties;
create trigger properties_updated_at before update on public.properties
  for each row execute function public.tocar_updated_at();

create index if not exists properties_orden_idx on public.properties (published, position);

-- 2. Seguridad a nivel de fila -----------------------------
alter table public.properties enable row level security;

-- Cualquiera puede leer las propiedades publicadas (es lo que muestra el sitio)
drop policy if exists "lectura publica de publicadas" on public.properties;
create policy "lectura publica de publicadas" on public.properties
  for select to anon using (published = true);

-- Las personas con sesión iniciada (los dueños) ven y editan todo
drop policy if exists "lectura completa autenticados" on public.properties;
create policy "lectura completa autenticados" on public.properties
  for select to authenticated using (true);

drop policy if exists "alta autenticados" on public.properties;
create policy "alta autenticados" on public.properties
  for insert to authenticated with check (true);

drop policy if exists "edicion autenticados" on public.properties;
create policy "edicion autenticados" on public.properties
  for update to authenticated using (true) with check (true);

drop policy if exists "borrado autenticados" on public.properties;
create policy "borrado autenticados" on public.properties
  for delete to authenticated using (true);

-- 3. Almacenamiento de fotos -------------------------------
insert into storage.buckets (id, name, public)
values ('propiedades', 'propiedades', true)
on conflict (id) do update set public = true;

drop policy if exists "fotos lectura publica" on storage.objects;
create policy "fotos lectura publica" on storage.objects
  for select to anon using (bucket_id = 'propiedades');

drop policy if exists "fotos alta autenticados" on storage.objects;
create policy "fotos alta autenticados" on storage.objects
  for insert to authenticated with check (bucket_id = 'propiedades');

drop policy if exists "fotos edicion autenticados" on storage.objects;
create policy "fotos edicion autenticados" on storage.objects
  for update to authenticated using (bucket_id = 'propiedades');

drop policy if exists "fotos borrado autenticados" on storage.objects;
create policy "fotos borrado autenticados" on storage.objects
  for delete to authenticated using (bucket_id = 'propiedades');

-- 4. Semilla: el catálogo que ya está publicado hoy --------
--    (on conflict do nothing: si ya existen, no se sobrescriben)
