  ('la-escondida-residencial', 'La Escondida Residencial', 'Metepec', 'Metepec, Estado de México', 'Casa', 'Venta', 6200000, 4, 4, 3, 310, 260, false, null, 'Privacidad total en un rincón arbolado de Metepec.', 'Casa de cuatro recámaras con estancia familiar, terraza con asador, jardín con árboles maduros y bodega. Desarrollo con pocas casas, ideal para familias que buscan tranquilidad.', array['Asador', 'Árboles maduros', 'Estancia familiar', 'Bodega', 'Pocas casas'], array['1580587771525-78b9dba3b914', '1493809842364-78817add7ffb', '1484154218962-a197022b5858', '1600607687939-ce8a6c25118c'], '{}', '{"location":"Metepec, State of Mexico","summary":"Complete privacy in a tree-lined corner of Metepec.","description":"Four-bedroom home with family room, terrace with grill, garden with mature trees and storage room. A small development, ideal for families seeking tranquility.","amenities":["Grill","Mature trees","Family room","Storage","Few homes"]}'::jsonb, true, 8),
  ('miranta-metepec', 'Miranta Metepec', 'Metepec', 'Metepec, Estado de México', 'Casa', 'Venta', 4390000, 3, 2.5, 2, 205, 160, false, null, 'Diseño funcional con acabados de lujo y excelente ubicación.', 'Casa con acabados premium, pisos de porcelanato, cancelería de aluminio negro y cocina equipada. A pocos minutos de Paseo Tollocan y Av. Tecnológico.', array['Cocina equipada', 'Porcelanato', 'Cancelería premium', 'Jardín', 'Vigilancia'], array['1605276374104-dee2a0ed3cd6', '1600566753190-17f0baa2a6c3', '1600573472550-8090b5e0745e', '1600210492486-724fe5c67fb0'], '{}', '{"location":"Metepec, State of Mexico","summary":"Functional design with luxury finishes and a great location.","description":"Home with premium finishes, porcelain floors, black aluminum window frames and a fully equipped kitchen. Just minutes from Paseo Tollocan and Av. Tecnológico.","amenities":["Equipped kitchen","Porcelain floors","Premium windows","Garden","Security"]}'::jsonb, true, 9),
  ('residencial-terentia', 'Residencial Terentia', 'Metepec', 'Metepec, Estado de México', 'Casa', 'Venta', 5790000, 3, 3.5, 2, 250, 190, false, null, 'Casa con doble altura y roof garden en privada exclusiva.', 'Espacios luminosos con doble altura en sala, family room en planta alta, vestidor en recámara principal y roof garden con medio baño. Privada con alberca y gimnasio.', array['Alberca', 'Gimnasio', 'Roof garden', 'Vestidor', 'Family room'], array['1600047509807-ba8f99d2cdde', '1600210492486-724fe5c67fb0', '1484154218962-a197022b5858', '1600607687939-ce8a6c25118c'], '{}', '{"location":"Metepec, State of Mexico","summary":"Home with double-height ceilings and roof garden in an exclusive community.","description":"Bright spaces with a double-height living room, upstairs family room, walk-in closet in the primary bedroom and a roof garden with half bath. The community has a pool and gym.","amenities":["Pool","Gym","Roof garden","Walk-in closet","Family room"]}'::jsonb, true, 10),
